def test_generation_two_objectives_bind_inheritance_research_and_materialization() -> (
    None
):
    packet = {
        "packet_id": "battle-004-red-generation-2-knowledge",
        "parent_artifact_sha256": "parent-sha",
        "parent_semantic_genome_sha256": "semantic-sha",
    }
    research = {"source_receipt_sha256": "research-sha"}

    red = _generation_2_objective("red", packet, research)
    blue = _generation_2_objective("blue", packet, research)

    for objective in (red, blue):
        assert packet["packet_id"] in objective
        assert packet["parent_artifact_sha256"] in objective
        assert packet["parent_semantic_genome_sha256"] in objective
        assert "first_plan_action" in objective
        assert research["source_receipt_sha256"] in objective
        assert "public target only" in objective
    assert "from app import import_zip" in red
    assert "callable import_zip(zip_path, destination)" in blue


def test_campaign_status_requires_both_lineages_and_both_judge_pairs() -> None:
    values = {
        "generation_1": {"status": "PASS"},
        "visibility": {"status": "PASS"},
        "g1_judge": {"status": "PASS", "judged_pair_count": 1},
        "g2_judge": {"status": "PASS", "judged_pair_count": 1},
        "red_spawn": {"status": "PASS"},
        "blue_spawn": {"status": "PASS"},
        "red_ack": {"status": "PASS"},
        "blue_ack": {"status": "PASS"},
        "selection": {"status": "PASS"},
        "observations": [{"status": "PASS"}] * 4,
        "fitness": [{"status": "PASS"}] * 4,
        "requests": [
            {"request": {"requested_action": "SPAWN_CHILD"}},
            {"request": {"requested_action": "SPAWN_CHILD"}},
        ],
        "deltas": [{"nonempty_semantic_delta": True}] * 2,
        "memory_evaluation": {"status": "PASS"},
        "artifact_integrity": {
            "status": "PASS",
            "slots": [
                {"slot_key": "generation-1:red", "matched": True},
                {"slot_key": "generation-1:blue", "matched": True},
                {"slot_key": "generation-2:red", "matched": True},
                {"slot_key": "generation-2:blue", "matched": True},
            ],
            "judge_replays": [
                {
                    "generation": 1,
                    "status": "PASS",
                    "matched": True,
                    "receipt_valid": True,
                },
                {
                    "generation": 2,
                    "status": "PASS",
                    "matched": True,
                    "receipt_valid": True,
                },
            ],
        },
    }

    assert _campaign_status(**values) == (
        "PASS",
        "two_generation_red_blue_lineage_evaluated",
    )

    values["blue_ack"] = {"status": "BLOCKED"}
    assert _campaign_status(**values) == (
        "BLOCKED",
        "spawn_inheritance_or_selection_blocked",
    )


def test_campaign_status_fails_closed_without_exact_integrity_sets() -> None:
    values = _passing_campaign_values()
    values.pop("artifact_integrity")
    assert _campaign_status(**values) == (
        "BLOCKED",
        "artifact_integrity_missing",
    )

    values = _passing_campaign_values()
    values["artifact_integrity"]["slots"][-1]["slot_key"] = "generation-2:red"
    assert _campaign_status(**values) == (
        "BLOCKED",
        "artifact_integrity_slot_set_invalid",
    )

    values = _passing_campaign_values()
    values["artifact_integrity"]["judge_replays"][1]["generation"] = 1
    assert _campaign_status(**values) == (
        "BLOCKED",
        "judge_replay_generation_set_invalid",
    )

    values = _passing_campaign_values()
    values["artifact_integrity"]["slots"][0]["matched"] = False
    assert _campaign_status(**values) == (
        "BLOCKED",
        "artifact_integrity_slot_mismatch",
    )

    values = _passing_campaign_values()
    values["g1_judge"]["status"] = "INSUFFICIENT_EVIDENCE"  # type: ignore[index]
    assert _campaign_status(**values) == (
        "BLOCKED",
        "judge_status_not_pass",
    )

    values = _passing_campaign_values()
    values["artifact_integrity"]["judge_replays"][0]["matched"] = False
    assert _campaign_status(**values) == (
        "BLOCKED",
        "judge_replay_mismatch",
    )

    values = _passing_campaign_values()
    values["artifact_integrity"]["judge_replays"][0]["receipt_valid"] = False
    assert _campaign_status(**values) == (
        "BLOCKED",
        "judge_replay_receipt_invalid",
    )


def test_preserved_slot_survives_source_mutation_and_detects_slot_mutation(
    tmp_path: Path,
) -> None:
    source = tmp_path / "pipeline" / "selected.py"
    source.parent.mkdir()
    source.write_text("ORIGINAL\n", encoding="utf-8")
    expected = hashlib.sha256(source.read_bytes()).hexdigest()
    slot = _preserve_selected_artifact(
        generation_dir=tmp_path / "generation-1",
        generation=1,
        team="blue",
        source=source,
        expected_sha256=expected,
    )
    pipeline = {
        "blue": {
            "selected_artifact_sha256": expected,
            "immutable_slot": slot,
        }
    }
    source.write_text("MUTATED SOURCE\n", encoding="utf-8")
    _assert_pipeline_slots({"red": pipeline["blue"], "blue": pipeline["blue"]})

    slot_path = Path(slot["path"])
    slot_path.chmod(0o644)
    slot_path.write_text("MUTATED SLOT\n", encoding="utf-8")
    with pytest.raises(RuntimeError, match="immutable slot changed"):
        _assert_pipeline_slots({"red": pipeline["blue"], "blue": pipeline["blue"]})


def test_integrity_receipt_requires_four_unique_slots_and_two_replays(
    tmp_path: Path,
) -> None:
    pipelines: dict[int, dict[str, dict[str, object]]] = {1: {}, 2: {}}
    for generation in (1, 2):
        for team in ("red", "blue"):
            path = tmp_path / f"g{generation}-{team}.py"
            path.write_text(f"{generation}:{team}\n", encoding="utf-8")
            sha = hashlib.sha256(path.read_bytes()).hexdigest()
            pipelines[generation][team] = {
                "selected_artifact_sha256": sha,
                "immutable_slot": {"path": str(path)},
            }
    judges = {}
    for generation in (1, 2):
        replay_path = tmp_path / f"replay-{generation}.json"
        replay_path.write_text(f'{{"generation": {generation}}}\n', encoding="utf-8")
        judges[generation] = {
            "exact_replay": {
                "status": "PASS",
                "matched": True,
                "path": str(replay_path),
                "sha256": hashlib.sha256(replay_path.read_bytes()).hexdigest(),
            }
        }
    receipt = _build_artifact_integrity_receipt(
        out_dir=tmp_path,
        pipelines=pipelines,  # type: ignore[arg-type]
        judges=judges,
    )
    assert receipt["status"] == "PASS"
    assert receipt["matched_slot_count"] == receipt["required_slot_count"] == 4
    assert receipt["matched_replay_count"] == receipt["required_replay_count"] == 2
    assert all(item["receipt_valid"] for item in receipt["judge_replays"])

    judges[1]["exact_replay"]["sha256"] = "0" * 64
    bad_replay = _build_artifact_integrity_receipt(
        out_dir=tmp_path,
        pipelines=pipelines,  # type: ignore[arg-type]
        judges=judges,
    )
    assert bad_replay["status"] == "FAIL"
    assert bad_replay["matched_replay_count"] == 1
    assert bad_replay["judge_replays"][0]["receipt_valid"] is False
    judges[1]["exact_replay"]["sha256"] = hashlib.sha256(
        (tmp_path / "replay-1.json").read_bytes()
    ).hexdigest()

    Path(receipt["slots"][0]["path"]).write_text("DRIFT\n", encoding="utf-8")
    failed = _build_artifact_integrity_receipt(
        out_dir=tmp_path,
        pipelines=pipelines,  # type: ignore[arg-type]
        judges=judges,
    )
    assert failed["status"] == "FAIL"
    assert failed["matched_slot_count"] == 3


def test_judge_fingerprint_normalizes_only_replay_workspace_paths(
    tmp_path: Path,
) -> None:
    red = tmp_path / "red.py"
    blue = tmp_path / "blue.py"
    stdout = tmp_path / "stdout.txt"
    stderr = tmp_path / "stderr.txt"
    red.write_text("red\n", encoding="utf-8")
    blue.write_text("blue\n", encoding="utf-8")
    stdout.write_text("same\n", encoding="utf-8")
    stderr.write_text("", encoding="utf-8")

    def judge(workspace: str) -> dict[str, object]:
        return {
            "status": "PASS",
            "verdict": "BLUE_SUCCESS",
            "judged_pair_count": 1,
            "attempts": [
                {
                    "pair_id": "red-0__blue-0",
                    "red_artifact": str(red),
                    "blue_artifact": str(blue),
                    "verdict": "BLUE_SUCCESS",
                    "exploit_confirmed_before_patch": True,
                    "exploit_blocked_after_patch": True,
                    "functionality_preserved": True,
                    "commands_run": [
                        {
                            "command": [
                                "docker",
                                "run",
                                "-v",
                                f"{workspace}:/workspace:rw",
                                "python@sha256:abc",
                            ],
                            "exit_code": 0,
                            "stdout_path": str(stdout),
                            "stderr_path": str(stderr),
                        }
                    ],
                }
            ],
        }

    assert _judge_fingerprint(
        judge=judge("/first/run"),  # type: ignore[arg-type]
        docker_image="python@sha256:abc",
        target_identity_sha256="a" * 64,
    ) == _judge_fingerprint(
        judge=judge("/second/run"),  # type: ignore[arg-type]
        docker_image="python@sha256:abc",
        target_identity_sha256="a" * 64,
    )


def test_required_child_research_query_rejects_stop_and_empty_questions() -> None:
    stop = {
        "request": {
            "requested_action": "STOP",
            "requested_research_questions": [],
        }
    }
    with pytest.raises(RuntimeError, match="required generation-2 child: STOP"):
        _required_child_research_query("blue", stop, {"status": "BLOCKED"})

    empty = {
        "request": {
            "requested_action": "SPAWN_CHILD",
            "requested_research_questions": [],
        }
    }
    with pytest.raises(RuntimeError, match="omitted a research question"):
        _required_child_research_query("blue", empty, {"status": "PASS"})

    valid = {
        "request": {
            "requested_action": "SPAWN_CHILD",
            "requested_research_questions": [
                "Which bounded variation should be tested?"
            ],
        }
    }
    assert _required_child_research_query("blue", valid, {"status": "PASS"}) == (
        "Which bounded variation should be tested?"
    )


